38	const createNodeContentEntries = async (
39	  node: ObsidianDiscourseNodeData,
40	  accountLocalId: string,
41	  plugin: DiscourseGraphPlugin,
42	): Promise<LocalContentDataInput[]> => {
43	  const variantsToCreate = getVariantsToCreate(node.changeTypes);
44	
45	  if (variantsToCreate.length === 0) {
46	    return [];
47	  }
48	
49	  const baseEntry = {
50	    author_local_id: accountLocalId,
51	    creator_local_id: accountLocalId,
52	    source_local_id: node.nodeInstanceId,
53	    created: node.created,
54	    last_modified: node.last_modified,
55	    scale: "document" as const,
56	  };
57	
58	  const entries: LocalContentDataInput[] = [];
59	
60	  // Create direct entry (title) if needed - will get embeddings
61	  if (variantsToCreate.includes("direct")) {
62	    entries.push({
63	      ...baseEntry,
64	      text: node.file.basename,
65	      variant: "direct",
66	      content_type: "text/plain",
67	      metadata: { filePath: node.file.path },
68	    });
69	  }
70	
71	  // Create full entry (content) if needed - no embeddings
72	  if (variantsToCreate.includes("full")) {
73	    try {
74	      const fullContent = await plugin.app.vault.read(node.file);
75	      entries.push({
76	        ...baseEntry,
77	        text: fullContent,
78	        variant: "full",
79	        content_type: "text/obsidian+markdown",
80	        metadata: node.frontmatter as Json,
81	      });
82	    } catch (error) {
83	      console.error(`Error reading file content for ${node.file.path}:`, error);
84	    }
85	  }
86	
87	  return entries;
88	};
