184	export const upsertNodesToSupabaseAsContentWithEmbeddings = async ({
185	  obsidianNodes,
186	  supabaseClient,
187	  context,
188	  accountLocalId,
189	  plugin,
190	}: {
191	  obsidianNodes: ObsidianDiscourseNodeData[];
192	  supabaseClient: DGSupabaseClient;
193	  context: SupabaseContext;
194	  accountLocalId: string;
195	  plugin: DiscourseGraphPlugin;
196	}): Promise<void> => {
197	  if (!context?.userId) {
198	    console.error("No Supabase context found.");
199	    return;
200	  }
201	
202	  if (obsidianNodes.length === 0) {
203	    return;
204	  }
205	
206	  // Create two entries per node: one "direct" (title) and one "full" (content)
207	  const allContentEntries = await convertObsidianNodeToLocalContent({
208	    nodes: obsidianNodes,
209	    accountLocalId,
210	    plugin,
211	  });
212	
213	  const directVariantEntries = allContentEntries.filter(
214	    (entry) => entry.variant === "direct",
215	  );
216	  const fullVariantEntries = allContentEntries.filter(
217	    (entry) => entry.variant === "full",
218	  );
219	
220	  let directEntriesWithEmbeddings: LocalContentDataInput[];
221	  try {
222	    directEntriesWithEmbeddings =
223	      await fetchEmbeddingsForNodes(directVariantEntries);
224	  } catch (error: unknown) {
225	    const errorMessage = error instanceof Error ? error.message : String(error);
226	    console.error(
227	      `upsertNodesToSupabaseAsContentWithEmbeddings: Embedding service failed – ${errorMessage}`,
228	    );
229	    throw new Error(errorMessage);
230	  }
231	
232	  if (directEntriesWithEmbeddings.length !== directVariantEntries.length) {
233	    console.error(
234	      "upsertNodesToSupabaseAsContentWithEmbeddings: Mismatch between direct variant entries and embedding counts.",
235	    );
236	    throw new Error(
237	      "upsertNodesToSupabaseAsContentWithEmbeddings: Mismatch between direct variant entries and embedding counts.",
238	    );
239	  }
240	
241	  const allEntriesToUpload = [
242	    ...directEntriesWithEmbeddings,
243	    ...fullVariantEntries,
244	  ];
245	
246	  const batchSize = 200;
247	
248	  const chunk = <T>(array: T[], size: number): T[][] => {
249	    const chunks: T[][] = [];
250	    for (let i = 0; i < array.length; i += size) {
251	      chunks.push(array.slice(i, i + size));
252	    }
253	    return chunks;
254	  };
255	
256	  await uploadBatches(
257	    chunk(allEntriesToUpload, batchSize),
258	    supabaseClient,
259	    context,
260	  );
261	};
