259	/**
260	 * Recursively order concepts by dependency so that dependents (e.g. instances)
261	 * come after their dependencies (e.g. schemas). When we look up a related
262	 * concept by id in `remainder`, we use the same id that appears in
263	 * schema_represented_by_local_id or local_reference_content — so that id
264	 * must equal some concept's source_local_id or it is reported as "missing".
265	 */
266	const orderConceptsRec = ({
267	  ordered,
268	  concept,
269	  remainder,
270	  processed,
271	}: {
272	  ordered: LocalConceptDataInput[];
273	  concept: LocalConceptDataInput;
274	  remainder: { [key: string]: LocalConceptDataInput };
275	  processed: Set<string>;
276	}): Set<string> => {
277	  // Add to processed at the start to prevent cycles
278	  processed.add(concept.source_local_id!);
279	  const relatedConceptIds = relatedConcepts(concept);
280	  let missing: Set<string> = new Set();
281	  while (relatedConceptIds.length > 0) {
282	    const relatedConceptId = relatedConceptIds.shift()!;
283	    if (processed.has(relatedConceptId)) continue;
284	    const relatedConcept = remainder[relatedConceptId];
285	    if (relatedConcept === undefined) {
286	      missing.add(relatedConceptId);
287	    } else {
288	      missing = new Set([
289	        ...missing,
290	        ...orderConceptsRec({
291	          ordered,
292	          concept: relatedConcept,
293	          remainder,
294	          processed,
295	        }),
296	      ]);
297	      delete remainder[relatedConceptId];
298	    }
299	  }
300	  ordered.push(concept);
301	  delete remainder[concept.source_local_id!];
302	  return missing;
303	};
304	
305	/**
306	 * Order concepts so dependencies (schemas) are before dependents (instances).
307	 * Assumes every concept has source_local_id; concepts without it are excluded
308	 * from the map (same as Roam). A node type is "missing" when an instance
309	 * references schema_represented_by_local_id = X but no concept in the input
310	 * has source_local_id === X (e.g. schema not included, or id vs nodeTypeId mismatch).
311	 */
312	export const orderConceptsByDependency = (
313	  concepts: LocalConceptDataInput[],
314	): { ordered: LocalConceptDataInput[]; missing: string[] } => {
315	  if (concepts.length === 0) return { ordered: concepts, missing: [] };
316	  const conceptById: { [key: string]: LocalConceptDataInput } =
317	    Object.fromEntries(
318	      concepts
319	        .filter((c) => c.source_local_id != null && c.source_local_id !== "")
320	        .map((c) => [c.source_local_id!, c]),
321	    );
322	  const ordered: LocalConceptDataInput[] = [];
323	  let missing: Set<string> = new Set();
324	  const processed: Set<string> = new Set();
325	  while (Object.keys(conceptById).length > 0) {
326	    const first = Object.values(conceptById)[0];
327	    if (!first) break;
328	    missing = new Set([
329	      ...missing,
330	      ...orderConceptsRec({
331	        ordered,
332	        concept: first,
333	        remainder: conceptById,
334	        processed,
335	      }),
336	    ]);
337	    if (missing.size > 0) console.error(`missing: ${[...missing].join(", ")}`);
338	  }
339	  return { ordered, missing: Array.from(missing) };
340	};
