  } finally {
    phases[phase] = Math.round(performance.now() - phaseStart);
  }
};

const syncTelemetryContext = ({
  attemptId,
  worker,
  userUid,
  syncFunction,
  context,
  startTime,
  claimed,
  phases,
  status,
  reason,
  nextUpdateTime,
  lastUpdateTime,
