102	export const fetchEmbeddingsForNodes = async (
103	  nodes: LocalContentDataInput[],
104	): Promise<LocalContentDataInput[]> => {
105	  const allEmbeddings: number[][] = [];
106	  const allNodesTexts = nodes.map((node) => node.text || "");
107	
108	  for (let i = 0; i < allNodesTexts.length; i += EMBEDDING_BATCH_SIZE) {
109	    const batch = allNodesTexts.slice(i, i + EMBEDDING_BATCH_SIZE);
110	    const response = await fetch(nextApiRoot() + "/embeddings/openai/small", {
111	      method: "POST",
112	      headers: { "Content-Type": "application/json" },
113	      body: JSON.stringify({ input: batch }),
114	    });
115	
116	    if (!response.ok) {
117	      let errorData;
118	      try {
119	        errorData = (await response.json()) as { error: string };
120	      } catch (e) {
121	        errorData = {
122	          error: `Server responded with ${response.status}: ${await response.text()}`,
123	        };
124	      }
125	      throw new Error(
126	        `API Error (${response.status}) processing batch ${
127	          i / EMBEDDING_BATCH_SIZE + 1
128	        }: ${errorData.error || "Failed to fetch embeddings"}`,
129	      );
130	    }
131	
132	    const data = (await response.json()) as EmbeddingApiResponse;
133	    if (!data || !Array.isArray(data.data)) {
134	      throw new Error(
135	        `Invalid API response format for batch ${
136	          i / EMBEDDING_BATCH_SIZE + 1
137	        }. Expected 'data' array.`,
138	      );
139	    }
140	    const batchEmbeddings = data.data.map((item) => item.embedding);
141	    allEmbeddings.push(...batchEmbeddings);
142	  }
143	
144	  if (nodes.length !== allEmbeddings.length) {
145	    throw new Error(
146	      `Mismatch between nodes (${nodes.length}) and embeddings (${allEmbeddings.length})`,
147	    );
148	  }
149	
150	  return nodes.map((node, i) => ({
151	    ...node,
152	    embedding_inline: {
153	      model: EMBEDDING_MODEL,
154	      vector: allEmbeddings[i] as number[],
155	    },
156	  }));
157	};
